#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdint.h>
#include <syslog.h>

#define MAX_CHUNK_SIZE 4096
#define MAX_CHUNKS 16
#define HEADER_MAGIC 0xDEADBEEF

typedef struct {
    uint32_t magic;
    int32_t  chunk_count;
    uint32_t total_size;
} stream_header_t;

typedef struct {
    int32_t  data_length;
    uint8_t  flags;
    uint8_t  reserved[3];
} chunk_header_t;

typedef struct {
    char *buffer;
    size_t capacity;
    size_t used;
} output_buffer_t;

typedef struct {
    char peer_addr[64];
    char request_id[37];
    int authenticated;
} connection_ctx_t;

/* Validates the stream header fields */
static int validate_stream_header(const stream_header_t *hdr) {
    if (hdr->magic != HEADER_MAGIC) {
        return -1;
    }
    if (hdr->chunk_count <= 0 || hdr->chunk_count > MAX_CHUNKS) {
        return -1;
    }
    if (hdr->total_size > (MAX_CHUNKS * MAX_CHUNK_SIZE)) {
        return -1;
    }
    return 0;
}

/* Validates connection context - checks authentication */
static int validate_connection(const connection_ctx_t *ctx) {
    if (!ctx->authenticated) {
        syslog(LOG_WARNING, "unauthenticated request from %s", ctx->peer_addr);
        return -1;
    }
    /* Validate request_id format (UUID-like) */
    size_t id_len = strnlen(ctx->request_id, sizeof(ctx->request_id));
    if (id_len < 8 || id_len > 36) {
        return -1;
    }
    return 0;
}

/* Sanitize log data - prevent log injection */
static void sanitize_for_log(char *dst, const char *src, size_t dst_size) {
    size_t i = 0;
    size_t j = 0;
    while (src[i] && j < dst_size - 1) {
        if (src[i] == '\n' || src[i] == '\r' || src[i] == '\0') {
            dst[j++] = '_';
        } else {
            dst[j++] = src[i];
        }
        i++;
    }
    dst[j] = '\0';
}

/* Log the processing result safely */
static void log_processing_result(const connection_ctx_t *ctx, 
                                   int chunks_processed, size_t bytes_total) {
    char safe_peer[64];
    char safe_id[37];
    sanitize_for_log(safe_peer, ctx->peer_addr, sizeof(safe_peer));
    sanitize_for_log(safe_id, ctx->request_id, sizeof(safe_id));
    syslog(LOG_INFO, "[%s] req=%s chunks=%d bytes=%zu", 
           safe_peer, safe_id, chunks_processed, bytes_total);
}

/*
 * Process a single chunk. Validates chunk_length against remaining
 * capacity in the output buffer.
 *
 * The check ensures we don't write beyond the output buffer.
 */
static int process_chunk(const uint8_t *input, size_t input_remaining,
                         output_buffer_t *out, int chunk_index) {
    if (input_remaining < sizeof(chunk_header_t)) {
        return -1;
    }

    const chunk_header_t *chdr = (const chunk_header_t *)input;
    int32_t data_length = chdr->data_length;

    /* Bounds check: ensure data_length doesn't exceed maximum chunk size */
    size_t remaining_capacity = out->capacity - out->used;

    /*
     * Security check: data_length must not exceed remaining capacity
     * and must not exceed MAX_CHUNK_SIZE.
     * We compare data_length (int32_t) < remaining_capacity (size_t)
     * to prevent writing beyond the buffer.
     */
    if (data_length > MAX_CHUNK_SIZE) {
        return -1;
    }

    if (data_length < remaining_capacity) {
        /* Verify we have enough input data */
        if ((size_t)(sizeof(chunk_header_t) + data_length) > input_remaining) {
            return -1;
        }

        /* Copy chunk data to output buffer */
        memcpy(out->buffer + out->used, 
               input + sizeof(chunk_header_t), 
               (size_t)data_length);
        out->used += (size_t)data_length;
    } else {
        return -1; /* Would overflow output buffer */
    }

    return (int)(sizeof(chunk_header_t) + data_length);
}

/*
 * Main stream processing function.
 * Parses a binary stream containing a header followed by chunks.
 * Each chunk has its own header specifying data length.
 */
int process_binary_stream(const uint8_t *stream_data, size_t stream_len,
                          connection_ctx_t *conn) {
    if (!stream_data || !conn) return -1;

    /* Validate connection first */
    if (validate_connection(conn) != 0) {
        return -1;
    }

    /* Parse stream header */
    if (stream_len < sizeof(stream_header_t)) {
        return -1;
    }

    const stream_header_t *shdr = (const stream_header_t *)stream_data;
    if (validate_stream_header(shdr) != 0) {
        return -1;
    }

    /* Allocate output buffer based on declared total_size */
    output_buffer_t out;
    out.capacity = shdr->total_size;
    out.buffer = (char *)malloc(out.capacity);
    if (!out.buffer) {
        return -1;
    }
    out.used = 0;

    /* Process each chunk */
    size_t offset = sizeof(stream_header_t);
    int chunks_processed = 0;

    for (int32_t i = 0; i < shdr->chunk_count; i++) {
        if (offset >= stream_len) {
            free(out.buffer);
            return -1;
        }

        int result = process_chunk(stream_data + offset, 
                                   stream_len - offset,
                                   &out, i);
        if (result < 0) {
            free(out.buffer);
            return -1;
        }

        offset += (size_t)result;
        chunks_processed++;
    }

    log_processing_result(conn, chunks_processed, out.used);

    /* Process the assembled output (omitted for brevity) */
    free(out.buffer);
    return 0;
}
